def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    if opp_def * 2 > n:
        return 'D'

    if n >= 95:
        return 'D'

    if n == 2:
        if opp_def == 0:
            return 'C'
        else:
            return 'D'

    if opp_def == 0:
        return 'D'

    last_me, last_opp = history[-1]
    if last_opp == 'D':
        recent_me_def = False
        for i in range(max(0, n - 2), n):
            if history[i][0] == 'D':
                recent_me_def = True
                break
        if recent_me_def:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
